{{ (function(){
  function unwrap(d){
    if (d && d.output !== undefined) d = d.output;
    if (d && d.body   !== undefined) d = d.body;
    if (typeof d === string) { try { d = JSON.parse(d); } catch(e) { d = null; } }
    return (d && d.records) || (Array.isArray(d) ? d : []);
  }
  return {
    accounts: unwrap(AccountMigration.data),
    opps: unwrap((typeof OppMigration !== undefined) ? OppMigration.data : null)
  };
})() }}

