* { box-sizing: border-box; }

.app {
  min-height: calc(var(--appsmith-ui-height) * 1px);
  width: calc(var(--appsmith-ui-width) * 1px);
  border-radius: var(--appsmith-theme-borderRadius);
  box-shadow: var(--appsmith-theme-boxShadow);
  padding: 20px 22px;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, system-ui, sans-serif;
  background: #ffffff;
  color: #1b1f27;
  font-size: 13px;
}

.header { margin-bottom: 14px; }
.header h1 { font-size: 18px; font-weight: 700; margin: 0 0 2px; letter-spacing: -0.01em; }
.header .sub { color: #6b7280; font-size: 12px; }

/* Tabs */
.tabs { display: flex; gap: 4px; border-bottom: 1px solid #e6e8ec; margin-bottom: 16px; }
.tab {
  padding: 8px 14px; cursor: pointer; font-weight: 600; font-size: 13px;
  color: #6b7280; border-bottom: 2px solid transparent; margin-bottom: -1px; user-select: none;
}
.tab:hover { color: #1b1f27; }
.tab.active { color: var(--appsmith-theme-primaryColor, #6229e6); border-bottom-color: var(--appsmith-theme-primaryColor, #6229e6); }

/* KPI cards */
.kpis { display: grid; grid-template-columns: repeat(4, 1fr); gap: 12px; margin-bottom: 16px; }
.kpi { border: 1px solid #e6e8ec; border-radius: 10px; padding: 12px 14px; background: #fbfbfd; }
.kpi .k-label { font-size: 11px; color: #6b7280; text-transform: uppercase; letter-spacing: 0.04em; font-weight: 600; display:flex; align-items:center; gap:6px; }
.kpi .k-value { font-size: 24px; font-weight: 700; margin-top: 4px; line-height: 1.1; }
.kpi .k-sub { font-size: 11px; color: #8a94a6; margin-top: 2px; }
.kpi.total { background: #f3f0ff; border-color: #e2d9ff; }
.kpi.conv { background: #eef7f0; border-color: #cfe8d6; }
.kpi.clickable-kpi { cursor: pointer; transition: box-shadow 0.15s, border-color 0.15s; }
.kpi.clickable-kpi:hover { border-color: var(--appsmith-theme-primaryColor, #6229e6); box-shadow: 0 2px 8px rgba(98,41,230,0.12); }
.kpi .zoom { font-size: 10px; color: var(--appsmith-theme-primaryColor, #6229e6); font-weight: 700; margin-left: 4px; }
.dot { width: 9px; height: 9px; border-radius: 50%; display: inline-block; }
.mini-badge { font-size: 9px; font-weight: 700; color: #1f9d55; background: #e7f5ec; border-radius: 10px; padding: 1px 6px; margin-left: 4px; vertical-align: middle; }
.controls-left { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }

/* Controls */
.controls { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-bottom: 10px; flex-wrap: wrap; }
.seg-toggle { display: inline-flex; background: #f1f2f5; border-radius: 8px; padding: 3px; }
.seg-toggle button {
  border: none; background: none; padding: 6px 12px; border-radius: 6px; cursor: pointer;
  font-weight: 600; font-size: 12px; color: #6b7280;
}
.seg-toggle button.active { background: #fff; color: #1b1f27; box-shadow: 0 1px 2px rgba(0,0,0,0.08); }
.search { position: relative; }
.search input {
  border: 1px solid #e0e2e8; border-radius: 8px; padding: 7px 10px 7px 30px; font-size: 12px;
  width: 240px; outline: none; background: #fff;
}
.search input:focus { border-color: var(--appsmith-theme-primaryColor, #6229e6); }
.search .ico { position: absolute; left: 10px; top: 50%; transform: translateY(-50%); color: #9aa0ac; font-size: 13px; }

/* Table / tree */
.tree { border: 1px solid #e6e8ec; border-radius: 10px; overflow: hidden; }
.thead, .row { display: grid; grid-template-columns: minmax(240px, 2.4fr) 78px 1fr 68px; align-items: center; }
.thead {
  background: #f7f8fa; border-bottom: 1px solid #e6e8ec; font-size: 11px; text-transform: uppercase;
  letter-spacing: 0.03em; color: #8a94a6; font-weight: 700; padding: 9px 14px;
}
.thead .num, .row .num { text-align: right; }
.row { padding: 8px 14px; border-bottom: 1px solid #f0f1f4; cursor: default; }
.row:last-child { border-bottom: none; }
.row.clickable { cursor: pointer; }
.row.clickable:hover { background: #fafbfc; }
.row.lvl0 { font-weight: 650; }
.row.lvl1 { background: #fcfcfd; }
.row.lvl2 { background: #fafbfc; }
.row.leaf { background: #f7f8fa; }
.name-cell { display: flex; align-items: center; gap: 7px; min-width: 0; }
.caret { width: 14px; text-align: center; color: #9aa0ac; font-size: 10px; transition: transform 0.12s; flex: none; }
.caret.open { transform: rotate(90deg); }
.name-txt { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.count-big { font-variant-numeric: tabular-nums; font-weight: 600; }
.mig-pct { text-align: right; font-variant-numeric: tabular-nums; font-weight: 600; }

/* stacked bar */
.bar { display: flex; height: 8px; width: 120px; flex: none; border-radius: 4px; overflow: hidden; background: #eef0f3; }
.bar span { display: block; height: 100%; }
.bar-wrap { display: flex; align-items: center; gap: 10px; }
.bar-legend { font-size: 11px; color: #8a94a6; font-variant-numeric: tabular-nums; white-space: nowrap; }

/* account leaf badges */
.acct { display: flex; align-items: center; gap: 8px; padding: 5px 14px 5px 44px; border-bottom: 1px solid #f0f1f4; font-size: 12px; }
.acct:last-child { border-bottom: none; }
.badge { font-size: 10px; font-weight: 700; padding: 2px 7px; border-radius: 20px; color: #fff; white-space: nowrap; }

/* opportunity leaf rows */
.opp-row { display: grid; grid-template-columns: 1fr auto; align-items: center; gap: 12px; padding: 7px 14px; border-bottom: 1px solid #f0f1f4; }
.opp-row:last-child { border-bottom: none; }
.opp-row:hover { background: #fafbfc; }
.opp-left { display: flex; align-items: flex-start; gap: 8px; min-width: 0; }
.opp-txt { min-width: 0; }
.opp-acct { font-weight: 600; font-size: 12.5px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.opp-meta { font-size: 11px; color: #8a94a6; margin-top: 1px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.opp-amt { font-variant-numeric: tabular-nums; font-weight: 600; font-size: 12.5px; white-space: nowrap; }
.opp-row .badge { margin-top: 1px; }

/* empty / placeholder */
.empty, .placeholder { text-align: center; padding: 40px 24px; color: #6b7280; }
.empty h3, .placeholder h3 { color: #1b1f27; font-size: 15px; margin: 0 0 8px; }
.empty code { background: #f1f2f5; padding: 1px 6px; border-radius: 4px; font-size: 12px; }
.empty ol { text-align: left; max-width: 460px; margin: 14px auto 0; line-height: 1.7; font-size: 12px; }
.pill { display:inline-block; background:#f3f0ff; color:#6229e6; border-radius:20px; padding:3px 10px; font-size:11px; font-weight:600; margin-bottom:10px; }

srcDoc.js:
/**
 * FULL FLEX – Commercial Offering Migration Dashboard (Appsmith Custom Widget)
 * Vanilla JS (no build step). Two tabs:
 *   Account View       – appsmith.model.accounts (AccountMigration: active-contract accounts)
 *   Migrations-Pipeline – appsmith.model.opps    (OppMigration: Hire_2_0__c = true opps)
 *
 * Batch migration logic: accounts on an active contract are migrated in
 * quarterly batches. A batch account gets a migration-potential opp
 * (Hire_2_0__c = true) → "In Migration". Once won, the account flag
 * New_Commercial_Offering__c flips true → "Migriert". Everything else
 * active-but-unflagged is "Noch offen" (pool for future batches).
 */

var ACC_SEGMENTS = [
  { key: "migrated",    label: "Migriert",     color: "#1f9d55" },
  { key: "inMigration", label: "In Migration", color: "#e0a800" },
  { key: "open",        label: "Noch offen",   color: "#8a94a6" }
];
var PIPE_SEGMENTS = [
  { key: "open", label: "Offen",     color: "#3b82f6" },
  { key: "won",  label: "Gewonnen",  color: "#1f9d55" },
  { key: "lost", label: "Verloren",  color: "#e5484d" }
];
function segColor(segs, k) { for (var i = 0; i < segs.length; i++) if (segs[i].key === k) return segs[i].color; return "#8a94a6"; }
function segLabel(segs, k) { for (var i = 0; i < segs.length; i++) if (segs[i].key === k) return segs[i].label; return k; }

var STAGE_ORDER = ["In Discussion", "Ready for Sales", "Demo Held", "Pitch & Negotiation",
  "Offer", "Contract received", "Closed Won", "Closed Lost"];

var BUCKETS = [
  { key: "overdue", label: "Überfällig (CloseDate vergangen)", max: -1 },
  { key: "b30",  label: "≤ 30 Tage",     max: 30 },
  { key: "b90",  label: "31 – 90 Tage",  max: 90 },
  { key: "b180", label: "91 – 180 Tage", max: 180 },
  { key: "bmax", label: "> 180 Tage",    max: Infinity }
];

var state = {
  tab: "account",
  accGroupBy: "motion",    // motion | tl
  pipeGroupBy: "stage",    // stage | motion | tl | timeline
  pipeScope: "all",        // all | active
  search: "",
  expanded: {}
};

/* ---------- helpers ---------- */

function el(tag, cls, html) { var e = document.createElement(tag); if (cls) e.className = cls; if (html != null) e.innerHTML = html; return e; }
function esc(s) { return String(s == null ? "" : s).replace(/[&<>"]/g, function (c) { return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]; }); }
function pct(n, d) { return d ? Math.round((n / d) * 100) : 0; }

function looksLikeRecords(arr) { if (!Array.isArray(arr) || arr.length === 0) return false; var f = arr[0]; return !!(f && typeof f === "object" && (f.attributes || f.Id || f.Name)); }
function findRecords(x, depth) {
  if (x == null || depth > 6) return null;
  if (looksLikeRecords(x)) return x;
  if (Array.isArray(x)) return null;
  if (typeof x === "object") {
    if (looksLikeRecords(x.records)) return x.records;
    for (var k in x) { if (!Object.prototype.hasOwnProperty.call(x, k)) continue; var r = findRecords(x[k], depth + 1); if (r) return r; }
  }
  return null;
}
function modelArray(key) { var m = (window.appsmith && appsmith.model) || {}; var v = m[key]; if (Array.isArray(v)) return v; return findRecords(v, 0) || []; }

var fmtEur = (function () {
  try { var f = new Intl.NumberFormat("de-DE", { style: "currency", currency: "EUR", maximumFractionDigits: 0 }); return function (n) { return f.format(n || 0); }; }
  catch (e) { return function (n) { return "€" + Math.round(n || 0); }; }
})();
function fmtDate(s) { if (!s) return "–"; var d = new Date(s); if (isNaN(d)) return esc(s); var p = function (x) { return (x < 10 ? "0" : "") + x; }; return p(d.getDate()) + "." + p(d.getMonth() + 1) + "." + d.getFullYear(); }
function daysUntil(s) { var d = new Date(s); if (isNaN(d)) return Infinity; return Math.floor((d - new Date()) / 86400000); }

function emptyCounts(segs) { var c = { total: 0, amount: 0 }; segs.forEach(function (s) { c[s.key] = 0; c[s.key + "Amt"] = 0; }); return c; }
function addTo(c, segKey, amount) { c[segKey] += 1; c.total += 1; c.amount += (amount || 0); c[segKey + "Amt"] += (amount || 0); }
function convPct(c) { var d = c.won + c.lost; return d ? Math.round((c.won / d) * 100) : null; }

function stackedBar(counts, segs) {
  var bar = el("div", "bar");
  segs.forEach(function (s) {
    var w = counts.total ? (counts[s.key] / counts.total) * 100 : 0;
    if (w > 0) { var span = el("span"); span.style.width = w + "%"; span.style.background = s.color; span.title = s.label + ": " + counts[s.key]; bar.appendChild(span); }
  });
  return bar;
}
function segLegend(counts, segs) { return segs.map(function (s) { return '<span style="color:' + s.color + '">●</span> ' + counts[s.key]; }).join("&nbsp;&nbsp;"); }

function kpiCard(labelHtml, value, sub, cls, onClick) {
  var c = el("div", "kpi" + (cls ? " " + cls : "") + (onClick ? " clickable-kpi" : ""));
  c.appendChild(el("div", "k-label", labelHtml));
  c.appendChild(el("div", "k-value", value));
  if (sub) c.appendChild(el("div", "k-sub", sub));
  if (onClick) c.addEventListener("click", onClick);
  return c;
}
function segToggle(options, current, onPick) {
  var wrap = el("div", "seg-toggle");
  options.forEach(function (o) { var b = el("button", current === o[0] ? "active" : "", o[1]); b.addEventListener("click", function () { if (current !== o[0]) onPick(o[0]); }); wrap.appendChild(b); });
  return wrap;
}
function searchBox(placeholder) {
  var search = el("div", "search");
  search.appendChild(el("span", "ico", "🔍"));
  var input = el("input"); input.type = "text"; input.placeholder = placeholder; input.value = state.search;
  input.addEventListener("input", function (e) { state.search = e.target.value; rerenderBody(); });
  search.appendChild(input);
  return search;
}
function matches(rec, q, fields) { if (!q) return true; q = q.toLowerCase(); return fields.map(function (f) { return rec[f] || ""; }).join(" ").toLowerCase().indexOf(q) !== -1; }

var NONE_MOTION = "— ohne Motion", NONE_TL = "— ohne Team Lead", NONE_IC = "— ohne Owner";

// Salesforce GTM motion -> "Adjusted GTM Area" (display + grouping).
// Note: both Enterprise motions map to "EP" and therefore merge into one group.
var MOTION_MAP = {
  "Enterprise New Business": "EP",
  "Enterprise Retention": "EP",
  "Subscription Retention": "Mid-Market ACM",
  "Subscription New Business": "Mid-Market New Business",
  "Agency Sales": "Agency",
  "Inside Sales": "SMB"
};
function mapMotion(m) { return m ? (MOTION_MAP[m] || m) : NONE_MOTION; }

/* ---------- data derivation ---------- */

function rawOpps() { return modelArray("opps"); }

// Accounts (active contract) that have an OPEN migration-potential opp.
function openMigrationAccountSet() {
  var s = {};
  rawOpps().forEach(function (o) { if (o && o.IsClosed === false && o.AccountId) s[o.AccountId] = true; });
  return s;
}

function currentAccounts() {
  var openMP = openMigrationAccountSet();
  return modelArray("accounts").map(function (r) {
    var migrated = r.New_Commercial_Offering__c === true;
    return {
      id: r.Id,
      name: r.Name || "(ohne Name)",
      motion: mapMotion(r.GTM_Motion_Account__c),
      tl: r.Account_Owner_s_Manager__c || NONE_TL,
      ic: r.Account_Owner__c || NONE_IC,
      segment: migrated ? "migrated" : (openMP[r.Id] ? "inMigration" : "open")
    };
  });
}

function currentOpps() {
  var activeSet = {};
  modelArray("accounts").forEach(function (a) { activeSet[a.Id] = true; });
  return rawOpps().map(function (o) {
    var acc = o.Account || {};
    var status = !o.IsClosed ? "open" : (o.IsWon ? "won" : "lost");
    return {
      account: acc.Name || "(ohne Account)",
      name: o.Name || "(ohne Name)",
      motion: mapMotion(acc.GTM_Motion_Account__c),
      tl: acc.Account_Owner_s_Manager__c || NONE_TL,
      ic: acc.Account_Owner__c || NONE_IC,
      stage: o.StageName || "(ohne Stage)",
      status: status,
      segment: status,
      close: o.CloseDate,
      days: daysUntil(o.CloseDate),
      amount: o.Amount || 0,
      reach: o.Monthly_Reach_Budget__c,
      product: o.Product_Type__c,
      type: o.Contract_type__c,
      activity: o.LastActivityDate,
      accMigrated: acc.New_Commercial_Offering__c === true,
      inActive: !!activeSet[o.AccountId]
    };
  });
}

/* ---------- generic tree ---------- */

function buildTree(items, keys, segs) {
  var root = { counts: emptyCounts(segs), children: {}, _order: [] };
  items.forEach(function (it) {
    addTo(root.counts, it.segment, it.amount || 0);
    var node = root;
    for (var i = 0; i < keys.length; i++) {
      var k = it[keys[i]];
      if (!node.children[k]) { node.children[k] = { label: k, counts: emptyCounts(segs), children: {}, _order: [], items: [] }; node._order.push(k); }
      node = node.children[k];
      addTo(node.counts, it.segment, it.amount || 0);
      if (i === keys.length - 1) node.items.push(it);
    }
  });
  return root;
}
function sortedChildren(node) {
  return node._order.map(function (k) { return node.children[k]; }).sort(function (a, b) {
    if (b.counts.total !== a.counts.total) return b.counts.total - a.counts.total;
    return String(a.label).localeCompare(String(b.label));
  });
}
function groupRow(label, level, path, counts, segs, hasChildren, rightHtml) {
  var open = !!state.expanded[path];
  var row = el("div", "row lvl" + level + (hasChildren ? " clickable" : ""));
  var nameCell = el("div", "name-cell"); nameCell.style.paddingLeft = (level * 18) + "px";
  nameCell.appendChild(el("span", "caret" + (open ? " open" : ""), hasChildren ? "▶" : ""));
  nameCell.appendChild(el("span", "name-txt", esc(label)));
  row.appendChild(nameCell);
  row.appendChild(el("div", "num count-big", String(counts.total)));
  var barCell = el("div", ""); var bw = el("div", "bar-wrap");
  bw.appendChild(stackedBar(counts, segs));
  bw.appendChild(el("div", "bar-legend", segLegend(counts, segs)));
  barCell.appendChild(bw); row.appendChild(barCell);
  row.appendChild(el("div", "mig-pct", rightHtml));
  if (hasChildren) row.addEventListener("click", function () { state.expanded[path] = !state.expanded[path]; render(); });
  return row;
}

/* ---------- Account View ---------- */

function renderAccountView(container, accounts) {
  var total = accounts.length, counts = emptyCounts(ACC_SEGMENTS);
  accounts.forEach(function (a) { addTo(counts, a.segment, 0); });

  var kpis = el("div", "kpis");
  kpis.appendChild(kpiCard("Accounts (aktiver Vertrag)", String(total), pct(counts.migrated, total) + "% migriert", "total"));
  ACC_SEGMENTS.forEach(function (s) {
    var clickable = s.key === "inMigration" ? function () { state.tab = "pipeline"; state.pipeGroupBy = "stage"; state.expanded = {}; state.search = ""; render(); } : null;
    kpis.appendChild(kpiCard('<span class="dot" style="background:' + s.color + '"></span>' + s.label + (clickable ? ' <span class="zoom">↗ Stages</span>' : ''),
      String(counts[s.key]), pct(counts[s.key], total) + "% aller Accounts", null, clickable));
  });
  container.appendChild(kpis);

  var controls = el("div", "controls");
  controls.appendChild(segToggle([["motion", "Nach Motion"], ["tl", "Nach Team Lead"]], state.accGroupBy, function (v) { state.accGroupBy = v; state.expanded = {}; render(); }));
  controls.appendChild(searchBox("Account, IC, TL oder Motion suchen…"));
  container.appendChild(controls);

  var body = el("div"); body.id = "view-body"; container.appendChild(body);
  renderAccountBody(body, accounts);
}
function renderAccountBody(body, accounts) {
  body.innerHTML = "";
  var filtered = accounts.filter(function (a) { return matches(a, state.search, ["name", "motion", "tl", "ic"]); });
  var keys = state.accGroupBy === "motion" ? ["motion", "tl", "ic"] : ["tl", "ic"];
  var leafLevel = keys.length - 1;
  var tree = buildTree(filtered, keys, ACC_SEGMENTS);

  var treeEl = el("div", "tree");
  var head = el("div", "thead");
  head.appendChild(el("div", "", state.accGroupBy === "motion" ? "Motion / Team Lead / IC" : "Team Lead / IC"));
  head.appendChild(el("div", "num", "Accounts"));
  head.appendChild(el("div", "", "Verteilung"));
  head.appendChild(el("div", "num", "Migr. %"));
  treeEl.appendChild(head);

  if (!filtered.length) treeEl.appendChild(el("div", "row", '<div style="grid-column:1/-1;color:#8a94a6;padding:14px 0;text-align:center">Keine Treffer</div>'));
  else renderAcctNodes(treeEl, tree, 0, "acc", 0 === leafLevel);
  body.appendChild(treeEl);
}
function renderAcctNodes(container, node, level, path, isLeafLevel) {
  sortedChildren(node).forEach(function (child) {
    var childPath = path + "/" + child.label;
    var hasChildren = isLeafLevel ? child.items.length > 0 : child._order.length > 0;
    container.appendChild(groupRow(child.label, level, childPath, child.counts, ACC_SEGMENTS, hasChildren, pct(child.counts.migrated, child.counts.total) + "%"));
    if (state.expanded[childPath]) {
      if (isLeafLevel) {
        child.items.slice().sort(function (a, b) { return a.name.localeCompare(b.name); }).forEach(function (a) {
          var acct = el("div", "acct"); acct.style.paddingLeft = ((level + 1) * 18 + 26) + "px";
          var badge = el("span", "badge", segLabel(ACC_SEGMENTS, a.segment)); badge.style.background = segColor(ACC_SEGMENTS, a.segment);
          acct.appendChild(badge); acct.appendChild(el("span", "name-txt", esc(a.name)));
          container.appendChild(acct);
        });
      } else renderAcctNodes(container, child, level + 1, childPath, level + 1 === (state.accGroupBy === "motion" ? 2 : 1));
    }
  });
}

/* ---------- Migrations-Pipeline View ---------- */

function renderPipelineView(container, allOpps) {
  if (allOpps.length === 0) {
    var e = el("div", "empty");
    e.innerHTML = "<h3>Noch keine Pipeline-Daten verbunden</h3><p>Erwartet <code>appsmith.model.opps</code> aus der Query <code>OppMigration</code> (Opportunities mit <code>Hire_2_0__c = true</code>).</p>";
    container.appendChild(e); return;
  }
  var opps = state.pipeScope === "active" ? allOpps.filter(function (o) { return o.inActive; }) : allOpps;
  var counts = emptyCounts(PIPE_SEGMENTS);
  opps.forEach(function (o) { addTo(counts, o.status, o.amount); });
  var conv = convPct(counts);

  var kpis = el("div", "kpis");
  kpis.appendChild(kpiCard("Migrations-Opps", String(opps.length), "Σ " + fmtEur(counts.amount), "total"));
  PIPE_SEGMENTS.forEach(function (s) {
    kpis.appendChild(kpiCard('<span class="dot" style="background:' + s.color + '"></span>' + s.label,
      String(counts[s.key]), pct(counts[s.key], opps.length) + "% · " + fmtEur(counts[s.key + "Amt"])));
  });
  kpis.appendChild(kpiCard("Conversion", conv == null ? "–" : conv + "%", "gewonnen / (gew. + verl.)", "conv"));
  container.appendChild(kpis);

  var controls = el("div", "controls");
