      segment: migrated ? "migrated" : (openMP[r.Id] ? "inMigration" : "open")
    };
  });
}

function currentOpps() {
  var activeSet = {};
  modelArray("accounts").forEach(function (a) { activeSet[a.Id] = true; });
  return rawOpps().map(function (o) {
    var acc = o.Account || {};
    var status = !o.IsClosed ? "open" : (o.IsWon ? "won" : "lost");
    return {
      account: acc.Name || "(ohne Account)",
      name: o.Name || "(ohne Name)",
      motion: mapMotion(acc.GTM_Motion_Account__c),
      tl: acc.Account_Owner_s_Manager__c || NONE_TL,
      ic: acc.Account_Owner__c || NONE_IC,
      stage: o.StageName || "(ohne Stage)",
      status: status,
      segment: status,
      close: o.CloseDate,
      days: daysUntil(o.CloseDate),
      amount: o.Amount || 0,
      reach: o.Monthly_Reach_Budget__c,
      product: o.Product_Type__c,
      type: o.Contract_type__c,
      activity: o.LastActivityDate,
      accMigrated: acc.New_Commercial_Offering__c === true,
      inActive: !!activeSet[o.AccountId]
    };
  });
}

/* ---------- generic tree ---------- */

function buildTree(items, keys, segs) {
  var root = { counts: emptyCounts(segs), children: {}, _order: [] };
  items.forEach(function (it) {
    addTo(root.counts, it.segment, it.amount || 0);
    var node = root;
    for (var i = 0; i < keys.length; i++) {
      var k = it[keys[i]];
      if (!node.children[k]) { node.children[k] = { label: k, counts: emptyCounts(segs), children: {}, _order: [], items: [] }; node._order.push(k); }
      node = node.children[k];
      addTo(node.counts, it.segment, it.amount || 0);
      if (i === keys.length - 1) node.items.push(it);
    }
  });
  return root;
}
function sortedChildren(node) {
  return node._order.map(function (k) { return node.children[k]; }).sort(function (a, b) {
    if (b.counts.total !== a.counts.total) return b.counts.total - a.counts.total;
    return String(a.label).localeCompare(String(b.label));
  });
}
function groupRow(label, level, path, counts, segs, hasChildren, rightHtml) {
  var open = !!state.expanded[path];
  var row = el("div", "row lvl" + level + (hasChildren ? " clickable" : ""));
  var nameCell = el("div", "name-cell"); nameCell.style.paddingLeft = (level * 18) + "px";
  nameCell.appendChild(el("span", "caret" + (open ? " open" : ""), hasChildren ? "▶" : ""));
  nameCell.appendChild(el("span", "name-txt", esc(label)));
  row.appendChild(nameCell);
  row.appendChild(el("div", "num count-big", String(counts.total)));
  var barCell = el("div", ""); var bw = el("div", "bar-wrap");
  bw.appendChild(stackedBar(counts, segs));
  bw.appendChild(el("div", "bar-legend", segLegend(counts, segs)));
  barCell.appendChild(bw); row.appendChild(barCell);
  row.appendChild(el("div", "mig-pct", rightHtml));
  if (hasChildren) row.addEventListener("click", function () { state.expanded[path] = !state.expanded[path]; render(); });
  return row;
}

/* ---------- Account View ---------- */

function renderAccountView(container, accounts) {
  var total = accounts.length, counts = emptyCounts(ACC_SEGMENTS);
  accounts.forEach(function (a) { addTo(counts, a.segment, 0); });

  var kpis = el("div", "kpis");
