  ACC_SEGMENTS.forEach(function (s) {
    var clickable = s.key === "inMigration" ? function () { state.tab = "pipeline"; state.pipeGroupBy = "stage"; state.expanded = {}; state.search = ""; render(); } : null;
    kpis.appendChild(kpiCard('<span class="dot" style="background:' + s.color + '"></span>' + s.label + (clickable ? ' <span class="zoom">↗ Stages</span>' : ''),
      String(counts[s.key]), pct(counts[s.key], total) + "% aller Accounts", null, clickable));
  });
  container.appendChild(kpis);

  var controls = el("div", "controls");
  controls.appendChild(segToggle([["motion", "Nach Motion"], ["tl", "Nach Team Lead"]], state.accGroupBy, function (v) { state.accGroupBy = v; state.expanded = {}; render(); }));
  controls.appendChild(searchBox("Account, IC, TL oder Motion suchen…"));
  container.appendChild(controls);

  var body = el("div"); body.id = "view-body"; container.appendChild(body);
  renderAccountBody(body, accounts);
}
function renderAccountBody(body, accounts) {
  body.innerHTML = "";
  var filtered = accounts.filter(function (a) { return matches(a, state.search, ["name", "motion", "tl", "ic"]); });
  var keys = state.accGroupBy === "motion" ? ["motion", "tl", "ic"] : ["tl", "ic"];
  var leafLevel = keys.length - 1;
  var tree = buildTree(filtered, keys, ACC_SEGMENTS);

  var treeEl = el("div", "tree");
  var head = el("div", "thead");
  head.appendChild(el("div", "", state.accGroupBy === "motion" ? "Motion / Team Lead / IC" : "Team Lead / IC"));
  head.appendChild(el("div", "num", "Accounts"));
  head.appendChild(el("div", "", "Verteilung"));
  head.appendChild(el("div", "num", "Migr. %"));
  treeEl.appendChild(head);

  if (!filtered.length) treeEl.appendChild(el("div", "row", '<div style="grid-column:1/-1;color:#8a94a6;padding:14px 0;text-align:center">Keine Treffer</div>'));
  else renderAcctNodes(treeEl, tree, 0, "acc", 0 === leafLevel);
  body.appendChild(treeEl);
}
function renderAcctNodes(container, node, level, path, isLeafLevel) {
  sortedChildren(node).forEach(function (child) {
    var childPath = path + "/" + child.label;
    var hasChildren = isLeafLevel ? child.items.length > 0 : child._order.length > 0;
    container.appendChild(groupRow(child.label, level, childPath, child.counts, ACC_SEGMENTS, hasChildren, pct(child.counts.migrated, child.counts.total) + "%"));
    if (state.expanded[childPath]) {
      if (isLeafLevel) {
        child.items.slice().sort(function (a, b) { return a.name.localeCompare(b.name); }).forEach(function (a) {
          var acct = el("div", "acct"); acct.style.paddingLeft = ((level + 1) * 18 + 26) + "px";
          var badge = el("span", "badge", segLabel(ACC_SEGMENTS, a.segment)); badge.style.background = segColor(ACC_SEGMENTS, a.segment);
          acct.appendChild(badge); acct.appendChild(el("span", "name-txt", esc(a.name)));
          container.appendChild(acct);
        });
      } else renderAcctNodes(container, child, level + 1, childPath, level + 1 === (state.accGroupBy === "motion" ? 2 : 1));
    }
  });
}

/* ---------- Migrations-Pipeline View ---------- */

function renderPipelineView(container, allOpps) {
  if (allOpps.length === 0) {
    var e = el("div", "empty");
    e.innerHTML = "<h3>Noch keine Pipeline-Daten verbunden</h3><p>Erwartet <code>appsmith.model.opps</code> aus der Query <code>OppMigration</code> (Opportunities mit <code>Hire_2_0__c = true</code>).</p>";
    container.appendChild(e); return;
  }
  var opps = state.pipeScope === "active" ? allOpps.filter(function (o) { return o.inActive; }) : allOpps;
  var counts = emptyCounts(PIPE_SEGMENTS);
  opps.forEach(function (o) { addTo(counts, o.status, o.amount); });
  var conv = convPct(counts);

  var kpis = el("div", "kpis");
  kpis.appendChild(kpiCard("Migrations-Opps", String(opps.length), "Σ " + fmtEur(counts.amount), "total"));
  PIPE_SEGMENTS.forEach(function (s) {
    kpis.appendChild(kpiCard('<span class="dot" style="background:' + s.color + '"></span>' + s.label,
      String(counts[s.key]), pct(counts[s.key], opps.length) + "% · " + fmtEur(counts[s.key + "Amt"])));
  });
  kpis.appendChild(kpiCard("Conversion", conv == null ? "–" : conv + "%", "gewonnen / (gew. + verl.)", "conv"));
  container.appendChild(kpis);

  var controls = el("div", "controls");
  var left = el("div", "controls-left");
  left.appendChild(segToggle([["stage", "Nach Stage"], ["motion", "Nach Motion"], ["tl", "Nach Team Lead"], ["timeline", "Timeline"]], state.pipeGroupBy, function (v) { state.pipeGroupBy = v; state.expanded = {}; render(); }));
  left.appendChild(segToggle([["all", "Alle"], ["active", "Nur aktive Verträge"]], state.pipeScope, function (v) { state.pipeScope = v; state.expanded = {}; render(); }));
  controls.appendChild(left);
  controls.appendChild(searchBox("Account, Opportunity, Stage, IC, TL, Motion suchen…"));
  container.appendChild(controls);

  var body = el("div"); body.id = "view-body"; container.appendChild(body);
  renderPipelineBody(body, opps);
}
function renderPipelineBody(body, opps) {
  body.innerHTML = "";
  var filtered = opps.filter(function (o) { return matches(o, state.search, ["account", "name", "stage", "motion", "tl", "ic"]); });

  var treeEl = el("div", "tree");
  var head = el("div", "thead");
  var firstCol = state.pipeGroupBy === "stage" ? "Stage / Opportunity"
    : state.pipeGroupBy === "timeline" ? "CloseDate / Opportunity"
      : (state.pipeGroupBy === "motion" ? "Motion / Team Lead / IC" : "Team Lead / IC");
  head.appendChild(el("div", "", firstCol));
  head.appendChild(el("div", "num", "Opps"));
  head.appendChild(el("div", "", "Verteilung · Σ"));
  head.appendChild(el("div", "num", "Conv. %"));
  treeEl.appendChild(head);

  if (!filtered.length) treeEl.appendChild(el("div", "row", '<div style="grid-column:1/-1;color:#8a94a6;padding:14px 0;text-align:center">Keine Treffer</div>'));
  else if (state.pipeGroupBy === "stage") renderPipeOrdered(treeEl, filtered, "stage", STAGE_ORDER, function (o) { return o.stage; });
  else if (state.pipeGroupBy === "timeline") renderPipeTimeline(treeEl, filtered);
  else {
    var keys = state.pipeGroupBy === "motion" ? ["motion", "tl", "ic"] : ["tl", "ic"];
    renderPipeNodes(treeEl, buildTree(filtered, keys, PIPE_SEGMENTS), 0, "pipe", keys.length - 1);
  }
  body.appendChild(treeEl);
}
function pipeRightHtml(counts) {
  var c = convPct(counts);
  return (c == null ? "–" : c + "%");
}
function groupLegendAmt(counts) { return segLegend(counts, PIPE_SEGMENTS) + '&nbsp;&nbsp;<span style="color:#b8bdc7">Σ ' + fmtEur(counts.amount) + "</span>"; }
function pipeGroupRow(label, level, path, counts, hasChildren) {
  var open = !!state.expanded[path];
  var row = el("div", "row lvl" + level + (hasChildren ? " clickable" : ""));
  var nameCell = el("div", "name-cell"); nameCell.style.paddingLeft = (level * 18) + "px";
  nameCell.appendChild(el("span", "caret" + (open ? " open" : ""), hasChildren ? "▶" : ""));
  nameCell.appendChild(el("span", "name-txt", esc(label)));
  row.appendChild(nameCell);
  row.appendChild(el("div", "num count-big", String(counts.total)));
  var barCell = el("div", ""); var bw = el("div", "bar-wrap");
  bw.appendChild(stackedBar(counts, PIPE_SEGMENTS));
  bw.appendChild(el("div", "bar-legend", groupLegendAmt(counts)));
  barCell.appendChild(bw); row.appendChild(barCell);
  row.appendChild(el("div", "mig-pct", pipeRightHtml(counts)));
  if (hasChildren) row.addEventListener("click", function () { state.expanded[path] = !state.expanded[path]; render(); });
  return row;
}
function renderPipeOrdered(container, opps, prefix, order, keyOf) {
  var groups = {};
  opps.forEach(function (o) { var k = keyOf(o); (groups[k] || (groups[k] = { counts: emptyCounts(PIPE_SEGMENTS), items: [] })); addTo(groups[k].counts, o.status, o.amount); groups[k].items.push(o); });
  var keys = Object.keys(groups).sort(function (a, b) { var ia = order.indexOf(a), ib = order.indexOf(b); if (ia < 0) ia = 99; if (ib < 0) ib = 99; return ia - ib; });
  keys.forEach(function (k) {
    var g = groups[k]; var path = prefix + "/" + k;
    container.appendChild(pipeGroupRow(k, 0, path, g.counts, true));
    if (state.expanded[path]) g.items.slice().sort(oppSort).forEach(function (o) { container.appendChild(oppRow(o, 1)); });
  });
}
function renderPipeTimeline(container, opps) {
  var groups = BUCKETS.map(function (b) { return { bucket: b, counts: emptyCounts(PIPE_SEGMENTS), items: [] }; });
  opps.forEach(function (o) { for (var i = 0; i < BUCKETS.length; i++) { if (o.days <= BUCKETS[i].max) { addTo(groups[i].counts, o.status, o.amount); groups[i].items.push(o); break; } } });
  groups.forEach(function (g) {
    if (!g.items.length) return; var path = "pipe-tl/" + g.bucket.key;
    container.appendChild(pipeGroupRow(g.bucket.label, 0, path, g.counts, true));
    if (state.expanded[path]) g.items.slice().sort(oppSort).forEach(function (o) { container.appendChild(oppRow(o, 1)); });
  });
}
function renderPipeNodes(container, node, level, path, leafLevel) {
  sortedChildren(node).forEach(function (child) {
    var childPath = path + "/" + child.label;
    var hasChildren = level === leafLevel ? child.items.length > 0 : child._order.length > 0;
    container.appendChild(pipeGroupRow(child.label, level, childPath, child.counts, hasChildren));
    if (state.expanded[childPath]) {
      if (level === leafLevel) child.items.slice().sort(oppSort).forEach(function (o) { container.appendChild(oppRow(o, level + 1)); });
      else renderPipeNodes(container, child, level + 1, childPath, leafLevel);
    }
  });
}
function oppSort(a, b) { return (b.amount - a.amount) || (a.days - b.days); }
function oppRow(o, level) {
  var row = el("div", "opp-row"); row.style.paddingLeft = (level * 18 + 26) + "px";
  var badge = el("span", "badge", segLabel(PIPE_SEGMENTS, o.status)); badge.style.background = segColor(PIPE_SEGMENTS, o.status);
  var left = el("div", "opp-left"); left.appendChild(badge);
  var txt = el("div", "opp-txt");
  var acctLine = esc(o.account) + (o.accMigrated ? ' <span class="mini-badge">✓ migriert</span>' : "");
  txt.appendChild(el("div", "opp-acct", acctLine));
  var bits = [];
  bits.push(esc(o.stage));
  bits.push("Close " + fmtDate(o.close));
  if (o.product) bits.push(esc(o.product));
  if (o.reach) bits.push("REACH " + fmtEur(o.reach) + "/M");
  if (o.activity) bits.push("letzte Akt. " + fmtDate(o.activity));
  txt.appendChild(el("div", "opp-meta", esc(o.name) + " · " + bits.join(" · ")));
  left.appendChild(txt); row.appendChild(left);
  row.appendChild(el("div", "opp-amt", fmtEur(o.amount)));
  return row;
}

/* ---------- shell ---------- */

function rerenderBody() {
  var body = document.getElementById("view-body"); if (!body) return;
  if (state.tab === "account") renderAccountBody(body, currentAccounts());
  else renderPipelineBody(body, state.pipeScope === "active" ? currentOpps().filter(function (o) { return o.inActive; }) : currentOpps());
}
function render() {
  var root = document.getElementById("root"); if (!root) return;
  root.innerHTML = "";
  var app = el("div", "app");
  var header = el("div", "header");
  header.appendChild(el("h1", "", "FULL FLEX · Commercial Offering Migration"));
  header.appendChild(el("div", "sub", "Batch-Migration aktiver Verträge auf das neue Commercial Offering"));
  app.appendChild(header);

  var tabs = el("div", "tabs");
  [["account", "Account View"], ["pipeline", "Migrations-Pipeline"]].forEach(function (t) {
    var tab = el("div", "tab" + (state.tab === t[0] ? " active" : ""), t[1]);
    tab.addEventListener("click", function () { state.tab = t[0]; state.search = ""; render(); });
    tabs.appendChild(tab);
  });
  app.appendChild(tabs);

  if (state.tab === "account") {
    var accounts = currentAccounts();
    if (!accounts.length) { var e = el("div", "empty"); e.innerHTML = "<h3>Noch keine Daten verbunden</h3><p>Erwartet <code>appsmith.model.accounts</code> aus <code>AccountMigration</code>.</p>"; app.appendChild(e); }
    else renderAccountView(app, accounts);
  } else {
    renderPipelineView(app, currentOpps());
  }
  root.appendChild(app);
}

if (window.appsmith && appsmith.onReady) {
  appsmith.onReady(function () { render(); });
  if (appsmith.onModelChange) appsmith.onModelChange(function () { render(); });
} else { render(); }
